import React from 'react';

const Topbar = ({ user }) => {
  return (
    <div className="bg-white shadow-sm fixed top-0 left-0 right-0 h-16 flex items-center justify-between px-6 z-10">
      <div className="text-gray-800 font-medium">Instituto Tecnológico Superior</div>
      <div className="flex items-center space-x-4">
        <div className="text-gray-700">{user.name}</div>
        <div className="w-8 h-8 rounded-full bg-blue-500 flex items-center justify-center text-white font-medium">
          {user.name.charAt(0)}
        </div>
      </div>
    </div>
  );
};

export default Topbar;
